do $$declare tabla record;begin for tabla in select c.oid,n.nspname esquema,c.relname nombre from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and (c.relname='tenants' or c.relname like 'gestion_%' or c.relname='tenant_branding') loop if not (select relrowsecurity from pg_class where oid=tabla.oid) then raise exception 'La tabla %.% no tiene RLS',tabla.esquema,tabla.nombre;end if;if not exists(select 1 from pg_policy where polrelid=tabla.oid) then raise exception 'La tabla %.% no tiene políticas',tabla.esquema,tabla.nombre;end if;end loop;end$$;
